import {ACCOUNTS_EMAIL,deliveryMessage,emailDraft,whatsappNumber} from './delivery.js';
import {financialYear,financialSummary,parseCSV,mappedRows,transactionTypes,transferCandidates} from './accounting.js';
import{DEFAULT_SETTINGS,normalise,money,decimal,lineTotal,invoiceTotals,today,dateISO,displayDate,addDays,invoiceState,outstanding,ageing,report,newestInvoices}from './domain.js';
const views=['Dashboard','Instructing Attorneys','Matters','Invoices','Payments','Income and Expenses','Reports','Financial Statements','Settings'];
let view='Dashboard',data=normalise({}),raw={},connected=false,lastRefresh=null,loadError='',pending=null,saving=false,filter='',statusFilter='',from=today().slice(0,7)+'-01',to=today(),editorItems=[],pdfURL=null;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const textarea=(label,name,value='')=>`<div class="field full"><label for="${name}">${label}</label><textarea id="${name}" name="${name}">${esc(value)}</textarea></div>`;
const options=(rows,key,label,selected)=>rows.map(r=>`<option value="${esc(r[key])}" ${String(r[key])===String(selected)?'selected':''}>${esc(r[label])}</option>`).join('');
const select=(label,name,html)=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${html}</select></div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${heads.length}" class="empty">${connected?'No matching records.':'Connect your practice sheet to load records.'}</td></tr>`}</tbody></table></div>`;
const labelState=s=>({PARTIAL:'Partially Paid',ISSUING:'PDF pending',UNPAID:'Unpaid',PAID:'Paid',DRAFT:'Draft',CANCELLED:'Cancelled',OVERDUE:'Overdue'}[s]||s);
const badge=i=>{const s=invoiceState(i);return`<span class="badge ${s.toLowerCase()}">${labelState(s)}</span>`;};
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',6000);}
function connection(){document.body.dataset.connected=String(connected); $('#connection').textContent=saving?'Saving · awaiting readback':pending?'Save failed · retry available':connected?'Connected · refreshed '+new Intl.DateTimeFormat('en-ZA',{timeZone:'Africa/Johannesburg',hour:'2-digit',minute:'2-digit'}).format(lastRefresh):'Connection unavailable';}
async function refresh(){loadError='';$('#refresh').disabled=true;try{const r=await fetch('/api/data',{cache:'no-store'});const v=await r.json();if(!v.ok)throw Error(v.message||'Connection failed.');raw=v.data;data=normalise(raw);connected=true;lastRefresh=new Date();if(!v.schemaReady)loadError='Records loaded. Supporting columns are awaiting the backed-up schema setup; writes remain unavailable.';}catch(e){connected=false;loadError=e.message||'Could not load the practice sheet.';}finally{$('#refresh').disabled=false;connection();render();}return connected;}
async function save(action,payload){if(pending)throw Error('Resolve the existing pending save before submitting another change.');pending={action,payload,operationId:crypto.randomUUID()};return retry();}
async function retry(){if(!pending)return;const operation=pending;saving=true;connection();document.querySelectorAll('#modal button[type="submit"]').forEach(b=>b.disabled=true);try{const r=await fetch('/api/write',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(operation)});const v=await r.json();if(!v.ok||!v.verified)throw Error(v.message||'Save was not verified.');const ok=await refresh();if(!ok)throw Error('Backend acknowledged the save, but refresh failed. Retry will verify the same operation without duplicating it.');pending=null;saving=false;connection();toast('Saved · confirmed by the spreadsheet.');return v;}catch(e){saving=false;connection();toast(e.message);render();throw e;}finally{document.querySelectorAll('#modal button[type="submit"]').forEach(b=>b.disabled=false);}}
function modal(title,html,footer=''){if(pdfURL){URL.revokeObjectURL(pdfURL);pdfURL=null;}$('#modal-body').innerHTML=`<div class="modal-head"><h2>${title}</h2>${button('Close','close')}</div><div class="modal-content">${html}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();}
function close(){$('#modal').close();if(pdfURL){URL.revokeObjectURL(pdfURL);pdfURL=null;}}
function heading(title,subtitle,actions=''){return`<div class="heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function notices(){let n='';if(loadError)n+=`<div class="notice error"><strong>${connected?'Setup required':'Practice sheet unavailable'}</strong><p>${esc(loadError)}</p>${button('Retry connection','refresh')} ${button('Connection settings','settings')}</div>`;if(pending)n+=`<div class="notice error"><strong>Save awaiting confirmation</strong><p>Your submission is retained in this open session. Retry uses the same operation ID. Refresh before resolving a conflict. Closing the app may lose an unsaved submission.</p>${button('Retry pending save','retry')} ${button('Discard pending submission','discard')}</div>`;if(data.issues.length)n+=`<div class="notice"><strong>${data.issues.length} records need review</strong><p>Historical status is preserved. Unverified receipts and malformed dates are excluded from relevant totals.</p>${button('Review records','review')}</div>`;return n;}
function labelTables(){document.querySelectorAll('#app table').forEach(t=>{const labels=[...t.querySelectorAll('thead th')].map(th=>th.textContent);t.querySelectorAll('tbody tr').forEach(row=>[...row.children].forEach((td,i)=>td.dataset.label=labels[i]||''));});}
const navPaths=['M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','M3 21V7h18v14 M8 7V3h8v4 M7 11h2 M15 11h2 M7 15h2 M15 15h2','M3 7h7l2 2h9v12H3z M3 7V4h7l2 3','M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h7','M3 6h18v14H3z M3 10h18 M7 15h4','M4 5h16v14H4z M8 9h8 M8 13h3 M15 12v4','M4 20V4 M4 20h17 M8 16v-5 M13 16V7 M18 16v-8','M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'];
function render(){$('#nav').innerHTML=views.map(v=>`<button class="${view===v?'active':''}" data-action="navigate" data-id="${v}" aria-current="${view===v?'page':'false'}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${navPaths[v==='Settings'?7:v==='Financial Statements'?6:views.indexOf(v)]}"/></svg>${v}</button>`).join('');let html=notices();const content={Dashboard:dashboard,'Instructing Attorneys':firms,Matters:matters,Invoices:invoices,Payments:payments,'Income and Expenses':transactions,Reports:reports,'Financial Statements':financialStatements,Settings:settings};html+=content[view]();$('#app').innerHTML=html;labelTables();connection();}
function invoiceRows(list){return newestInvoices(list).map(i=>`<tr><td><strong>${esc(i.id||'Missing ID')}</strong><small>${displayDate(i.date)}</small></td><td>${esc(i.clientName)}<small>${esc(i.matterName)}</small></td><td>${displayDate(i.dueDate)}</td><td class="number">${money(i.amountCents)}</td><td class="number">${i.paidCents===null&&i.status==='PAID'?'Unverified':money(outstanding(i))}</td><td>${badge(i)}</td><td>${button('View','invoice',i.id)} ${button('Edit','editInvoice',i.id)}</td></tr>`);}
function dashboard(){const asOf=today(),year=Number(asOf.slice(0,4))-(Number(asOf.slice(5,7))<3?1:0),financialYearStart=year+'-03-01',financial=report(data,financialYearStart,asOf),r=report(data,asOf.slice(0,7)+'-01',asOf),priorStart=(year-1)+'-03-01',priorYear=Number(asOf.slice(0,4))-1,priorDay=Math.min(Number(asOf.slice(8,10)),new Date(Date.UTC(priorYear,Number(asOf.slice(5,7)),0)).getUTCDate()),priorEnd=priorYear+asOf.slice(4,8)+String(priorDay).padStart(2,'0'),prior=report(data,priorStart,priorEnd),b=ageing(data.invoices);const stats=[['Fees invoiced this financial year',financial.invoiced,displayDate(financialYearStart)+' – '+displayDate(asOf)+' · excludes drafts'],['Payments received this month',r.receipts,'Recorded income transactions'],['Outstanding fees',r.outstanding,'Historical PAID records preserved'],['Overdue balances',r.overdue,'Based on due dates'],['Recorded expenses',r.expenses,'Recorded expenses this month'],['Fees invoiced · previous-year comparison',prior.invoiced,displayDate(priorStart)+' – '+displayDate(priorEnd)+' · same period, invoiced fees']];return heading('Practice overview',new Intl.DateTimeFormat('en-ZA',{month:'long',year:'numeric',timeZone:'Africa/Johannesburg'}).format(new Date()),button('Record payment','newPayment')+button('Create invoice','newInvoice','','primary'))+`<div class="cards">${stats.map((s,index)=>`<div class="card ${index===2?'featured':''}"><div class="label">${s[0]}</div><div class="value">${connected?money(s[1]):'—'}</div><small>${s[2]}</small></div>`).join('')}</div><div class="split"><div class="panel"><div class="panel-head"><h2>Invoices to follow up</h2>${button('All invoices','navigate','Invoices')}</div>${table(['Invoice','Firm / matter','Due','Amount','Outstanding','Status',''],invoiceRows(data.invoices.filter(i=>outstanding(i)>0).slice(0,7)))}</div><div class="panel"><h2>Debtor ageing</h2>${['Current','1–30 days','31–60 days','61–90 days','Over 90 days'].map((l,i)=>`<div class="bar-row"><span>${l}</span><div class="bar"><span style="width:${b[i]/Math.max(...b,1)*100}%"></span></div><span>${connected?money(b[i]):'—'}</span></div>`).join('')}<p class="small">Days overdue. Invoices without valid due dates require review.</p></div></div>`;}
function searchToolbar(placeholder='Search records'){return`<div class="toolbar"><input id="search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(filter)}">${view==='Invoices'?`<select id="status-filter" aria-label="Invoice status"><option value="">All statuses</option>${['DRAFT','UNPAID','PARTIAL','PAID','OVERDUE','CANCELLED','ISSUING'].map(s=>`<option value="${s}" ${s===statusFilter?'selected':''}>${labelState(s)}</option>`).join('')}</select><input id="from" type="date" value="${from}" aria-label="From date"><input id="to" type="date" value="${to}" aria-label="To date"><label class="check"><input type="checkbox" id="date-filter">Filter dates</label>`:''}</div>`;}
function firms(){const list=data.firms.filter(f=>JSON.stringify(f).toLowerCase().includes(filter.toLowerCase()));return heading('Instructing attorneys','Firm accounts and their individual contacts.',button('Add firm','newFirm','','primary'))+`<div class="panel">${searchToolbar('Search firms or contacts')}${table(['Firm','Attention / contact','Invoiced','Outstanding','Actions'],list.map(f=>{const inv=data.invoices.filter(i=>i.clientId===f.id&&!['DRAFT','CANCELLED','ISSUING'].includes(i.status));return`<tr><td><strong>${esc(f.name)}</strong><small>${esc(f.address)}</small>${f.archived==='TRUE'?'<span class="badge">Archived</span>':''}</td><td>${esc(f.contact)}<small>${esc(f.email)} · ${esc(f.phone)}</small><small>${f.partners?.length||0} additional contacts</small></td><td class="number">${money(inv.reduce((s,i)=>s+i.amountCents,0))}</td><td class="number">${money(inv.reduce((s,i)=>s+outstanding(i),0))}</td><td>${button('Edit','firm',f.id)} ${button('Statement','statement',f.id)}</td></tr>`;}))}</div>`;}
function matterList(){const list=[...data.matters];for(const i of data.invoices){if(i.matterName&&!list.some(m=>m.title===i.matterName&&(m.clientId===i.clientId||m.clientName===i.clientName)))list.push({id:'invoice:'+i.id,title:i.matterName,clientId:i.clientId,clientName:i.clientName,status:'From invoice',description:'Historical invoice matter; save to create an editable matter record.'});}return list;}
function matters(){return heading('Matters','Billing matters linked to instructing firms.',button('Add matter','newMatter','','primary'))+`<div class="panel">${searchToolbar('Search matters')}${table(['Matter','Firm','Practice area','Opened','Status',''],matterList().filter(m=>JSON.stringify(m).toLowerCase().includes(filter.toLowerCase())).map(m=>`<tr><td><strong>${esc(m.title)}</strong><small>${esc(m.description)}</small></td><td>${esc(m.clientName)}</td><td>${esc(m.practiceArea)}</td><td>${displayDate(m.dateOpened)}</td><td>${esc(m.archived==='TRUE'?'Archived':m.status)}</td><td>${button('Edit','matter',m.id)}</td></tr>`))}</div>`;}
function invoices(){const list=data.invoices.filter(i=>`${i.id} ${i.clientName} ${i.matterName}`.toLowerCase().includes(filter.toLowerCase())&&(!statusFilter||invoiceState(i)===statusFilter));return heading('Invoices','Draft, issue and track professional fees.',button('Record payment','newPayment')+button('Create invoice','newInvoice','','primary'))+`<div class="panel">${searchToolbar('Search invoice number, firm or matter')}${table(['Invoice','Firm / matter','Due','Amount','Outstanding','Status',''],invoiceRows(list))}</div>`;}
function payments(){return heading('Payments','Receipts, invoice allocations and available credits.',button('Record payment','newPayment','','primary'))+`<div class="panel">${table(['Date','Invoice / firm','Received','Allocated','Credit','Reference / method',''],data.payments.map(p=>`<tr><td>${displayDate(p.date)}</td><td>${esc(p.invoiceId)}<small>${esc(data.firms.find(f=>f.id===p.clientId)?.name)}</small></td><td>${money(p.amountCents)}</td><td>${money(p.allocatedCents)}</td><td>${money(p.creditCents)}</td><td>${esc(p.reference)}<small>${esc(p.method)}</small></td><td>${p.reversed==='TRUE'?'<span class="badge">Reversed</span>':p.method==='Historical balance'?'<span class="badge">Historical balance</span>':button('Reverse','reverse',p.id)}</td></tr>`))}</div>`;}
function transactions(){return heading('Income and expenses','Recorded cash movements. Sheet5 is retained separately.',button('Record expense','expense')+button('Record income','income','','primary'))+`<div class="panel">${searchToolbar('Search description or category')}${table(['Date','Description','Type','Category','Amount','Actions'],data.transactions.filter(t=>JSON.stringify(t).toLowerCase().includes(filter.toLowerCase())).map(t=>`<tr><td>${displayDate(t.date)}${!dateISO(t.date)?'<small>Needs correction</small>':''}</td><td>${esc(t.description)}<small>${esc(t.reference)}</small></td><td>${esc(t.type||'Unclassified')}${t.reversed==='TRUE'?'<small>Reversed</small>':''}</td><td>${esc(t.category)}</td><td class="number">${esc(t.amount)}</td><td>${t.id&&!t.paymentId?button('Edit','transaction',t.id):''}${t.id?button('Receipt','receipt',t.id):'<small>Missing ID</small>'}${t.receiptFileId?`<a href="/api/file?id=${encodeURIComponent(t.receiptFileId)}" target="_blank">View file</a>`:''}</td></tr>`))}</div><div class="panel"><h2>Sheet5 · unlinked bank records</h2><p>${data.sheet5.length} entries preserved. No automatic merger or inclusion in cash totals.</p>${button('Inspect Sheet5','sheet5')}</div>`;}
function reports(){const r=report(data,from,to),b=ageing(data.invoices,to);return heading('Reports','Date-filtered cash, fee and debtor reports.',button('Export CSV','reportCSV')+button('Export PDF','reportPDF'))+`<div class="toolbar">${field('From','from',from,'date')}${field('To','to',to,'date')}${button('Apply dates','applyDates')}</div><div class="cards">${[['Fees invoiced',r.invoiced],['Receipts',r.receipts],['Expenses',r.expenses],['Cash surplus',r.surplus],['Outstanding',r.outstanding],['Overdue',r.overdue]].map(s=>`<div class="card"><div class="label">${s[0]}</div><div class="value">${connected?money(s[1]):'—'}</div></div>`).join('')}</div><div class="panel"><h2>Attorney balances</h2>${table(['Firm','Invoiced in period','Outstanding','Unallocated payment credits'],data.firms.map(f=>`<tr><td>${esc(f.name)}</td><td>${money(report({...data,invoices:data.invoices.filter(i=>i.clientId===f.id)},from,to).invoiced)}</td><td>${money(data.invoices.filter(i=>i.clientId===f.id).reduce((s,i)=>s+outstanding(i),0))}</td><td>${money(data.payments.filter(p=>p.clientId===f.id&&p.reversed!=='TRUE').reduce((s,p)=>s+Number(p.creditCents||0),0))}</td></tr>`))}</div><div class="panel"><h2>Matter billing</h2>${table(['Matter','Firm','Invoiced in period','Outstanding'],data.matters.map(m=>`<tr><td>${esc(m.title)}</td><td>${esc(m.clientName)}</td><td>${money(report({...data,invoices:data.invoices.filter(i=>i.matterId===m.id||!i.matterId&&i.matterName===m.title&&i.clientName===m.clientName)},from,to).invoiced)}</td><td>${money(data.invoices.filter(i=>i.matterId===m.id).reduce((s,i)=>s+outstanding(i),0))}</td></tr>`))}</div><div class="panel"><h2>Debtor ageing</h2>${table(['Current','1–30 days','31–60 days','61–90 days','Over 90 days'],['<tr>'+b.map(n=>'<td>'+money(n)+'</td>').join('')+'</tr>'])}</div>`;}
function settings(){const s=data.settings;return heading('Settings','Practice particulars, payment terms and connection status.')+`<div class="panel"><h2>Google Sheets connection</h2><p>${connected?'Connected to the authoritative Practice spreadsheet.':'Secure backend connection awaiting configuration.'}</p><a href="https://docs.google.com/spreadsheets/" target="_blank" rel="noopener">Open Practice spreadsheet</a><p class="small">Last refresh: ${lastRefresh?lastRefresh.toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg'}):'Not yet loaded'}. Pending saves: ${pending?1:0}.</p><p>Connection setup requires the deployed signed Apps Script backend, its shared secret and your approved account email. These are configured privately on the server.</p><p><a href="/Code_Working_Copy.txt" download>Download current Apps Script code</a> · Run initialisePractice after upgrading, then deploy a new version.</p>${button('Refresh connection','refresh')} ${button('Review missing IDs','migration')} ${button('Audit log','audit')}</div><form id="settings-form" class="panel"><h2>Practice and letterhead</h2><div class="fields">${field('Practice name','practiceName',s.practiceName)}${field('Letterhead subtitle','letterhead',s.letterhead)}${textarea('Practice address','address',s.address)}${field('Email','email',s.email,'email')}${field('Telephone / WhatsApp','phone',s.phone)}</div><div class="setting-section"></div><h2>Banking particulars · review before issue</h2><div class="fields">${field('Bank','bank',s.bank)}${field('Account name','accountName',s.accountName)}${field('Account number','accountNumber',s.accountNumber)}${field('Branch code','branchCode',s.branchCode)}</div><div class="setting-section"></div><h2>Rates and payment terms</h2><div class="fields">${field('Hourly rate (R)','hourlyRate',s.hourlyRate,'number','step="0.01" min="0"')}${field('Daily rate (R)','dailyRate',s.dailyRate,'number','step="0.01" min="0"')}${field('Fixed fee default (R)','fixedRate',s.fixedRate,'number','step="0.01" min="0"')}${field('Payment terms (days)','paymentDays',s.paymentDays,'number','min="0" max="365"')}${textarea('Payment terms','terms',s.terms)}</div><div class="setting-section"></div><h2>VAT</h2><label class="check"><input name="vatRegistered" type="checkbox" ${s.vatRegistered?'checked':''}>VAT registered</label><div class="fields">${field('VAT number','vatNumber',s.vatNumber)}${field('VAT rate (%)','vatRate',s.vatRate,'number','step="0.01" min="0" max="100"')}${select('Rate treatment','vatTreatment',`<option value="exclusive" ${s.vatTreatment==='exclusive'?'selected':''}>Exclusive of VAT</option><option value="inclusive" ${s.vatTreatment==='inclusive'?'selected':''}>Inclusive of VAT</option>`)}</div><p class="small">VAT applies to new invoices only. Historical amounts are preserved.</p><div class="setting-section"></div><h2>Private document folder</h2>${field('Google Drive folder ID','driveFolderId',s.driveFolderId)}<p class="small">Issued PDFs and attachments remain private. Use a dedicated private folder.</p><label class="check"><input name="detailsReviewed" type="checkbox" ${s.detailsReviewed?'checked':''}>I have reviewed the banking and VAT particulars.</label><div class="actions"><button class="primary" type="submit" ${!connected?'disabled':''}>Save settings</button></div></form>`;}
function firmForm(id){const f=data.firms.find(f=>f.id===id)||{partners:[]};if(f.partners===null)return toast('Invalid contact JSON must be reviewed in the spreadsheet first.');modal(id?'Edit instructing firm':'Add instructing firm',`<form id="firm-form" data-id="${esc(id)}"><div class="fields">${field('Firm name','Firm',f.name||'','text','required')}${field('Primary attention contact','Attorney',f.contact)}${field('Email','email',f.email,'email')}${field('WhatsApp / telephone','phone',f.phone)}${textarea('Billing address','address',f.address)}</div><h3>Additional attorneys / partners</h3><div id="contacts">${(f.partners||[]).map(c=>contactFields(c)).join('')}</div>${button('Add contact','addContact')}<label class="check"><input type="checkbox" name="archived" ${f.archived==='TRUE'?'checked':''}>Archive this firm</label><div class="modal-foot"><button type="submit" class="primary">Save firm</button></div></form>`);}
function contactFields(c={id:crypto.randomUUID()}){return`<div class="contact fields" data-id="${esc(c.id)}">${field('Contact name','contactName',c.name)}${field('Email','contactEmail',c.email,'email')}${field('WhatsApp number','contactPhone',c.phone)}${button('Remove contact','removeContact')}</div>`;}
function matterForm(id){const m=matterList().find(m=>m.id===id)||{};if(id?.startsWith('invoice:'))id='';modal(id?'Edit matter':'Add matter',`<form id="matter-form" data-id="${esc(id)}"><div class="fields">${field('Matter title','title',m.title,'text','required')}${select('Instructing firm','clientId','<option value="">Select firm</option>'+options(data.firms.filter(f=>f.archived!=='TRUE'),'id','name',m.clientId))}${field('Practice area','practiceArea',m.practiceArea)}${field('Opened','dateOpened',dateISO(m.dateOpened)||today(),'date','required')}${select('Status','status',['OPEN','PENDING','CLOSED'].map(s=>`<option ${s===m.status?'selected':''}>${s}</option>`).join(''))}${textarea('Description','description',m.description)}${textarea('Notes','notes',m.notes)}</div><label class="check"><input name="archived" type="checkbox" ${m.archived==='TRUE'?'checked':''}>Archive matter</label><div class="modal-foot"><button class="primary" type="submit">Save matter</button></div></form>`);}
function invoiceForm(id){const i=data.invoices.find(i=>i.id===id);if(i&&i.items===null)return toast('Review invalid line item JSON before editing.');editorItems=i?.items?.map(x=>({...x}))||[{id:crypto.randomUUID(),serviceDate:today(),description:'',quantity:'1',rate:data.settings.hourlyRate,rateUnit:'hr',kind:'fee'}];const amendment=i&&!['DRAFT','ISSUING'].includes(i.status);modal(i?'Edit invoice '+esc(i.id):'Create invoice',`<form id="invoice-form" data-id="${esc(id)}">${amendment?'<p class="notice">Changes retain this invoice number. The previous PDF remains private and the amendment is recorded in the audit log. The updated Apps Script deployment is required to save amendments.</p>'+textarea('Reason for amendment','amendmentReason',''):''}<div class="fields">${select('Instructing firm','clientId','<option value="">Select firm</option>'+options(data.firms.filter(f=>f.archived!=='TRUE'),'id','name',i?.clientId))}${select('Attention','partnerId','<option value="">Primary contact</option>')}${field('Matter / project name','matterName',i?.matterName,'text','list="matter-suggestions" required')}<datalist id="matter-suggestions"></datalist><input type="hidden" id="matterId" name="matterId" value="${esc(i?.matterId)}">${field('Reference','reference',i?.reference)}${field('Invoice date','date',dateISO(i?.date)||today(),'date','required')}${field('Due date','dueDate',dateISO(i?.dueDate)||addDays(today(),data.settings.paymentDays),'date','required')}</div><h3>Fees and disbursements</h3><div id="line-items"></div>${button('Add fee','addLine')} ${button('Add disbursement','addDisbursement')}<div id="invoice-totals" class="totals"></div><div class="modal-foot">${button('Preview','previewDraft')}${amendment?'<button type="submit" name="amend" class="primary">Save amended invoice</button>':'<button type="submit" name="draft" class="secondary">Save draft</button><button type="submit" name="issue" class="primary">Issue invoice</button>'}</div></form>`);fillFirmSelectors(i?.partnerId,i?.matterId);renderLines();}
function firmMatters(f){return data.matters.filter(m=>(m.clientId===f?.id||(!m.clientId&&m.clientName===f?.name))&&m.archived!=='TRUE');}
function fillFirmSelectors(partnerId='',matterId=''){const f=data.firms.find(f=>f.id===$('#clientId')?.value);if(!$('#invoice-form'))return;$('#partnerId').innerHTML='<option value="">'+esc(f?.contact||'Primary contact')+'</option>'+options(f?.partners||[],'id','name',partnerId);const names=[...new Set([...firmMatters(f).map(m=>m.title),...data.invoices.filter(i=>i.clientId===f?.id).map(i=>i.matterName)].filter(Boolean))];$('#matter-suggestions').innerHTML=names.map(n=>`<option value="${esc(n)}"></option>`).join('');const m=data.matters.find(m=>m.id===matterId);if(m&&!$('#matterName').value)$('#matterName').value=m.title;syncMatter();}
function syncMatter(){const f=data.firms.find(f=>f.id===$('#clientId')?.value),name=$('#matterName')?.value.trim();const m=firmMatters(f).find(m=>m.title===name&&m.clientId===f?.id);if($('#matterId'))$('#matterId').value=m?.id||'';}
function renderLines(){$('#line-items').innerHTML=editorItems.map((item,index)=>`<div class="line-item" data-index="${index}"><div><label>Service date</label><input data-key="serviceDate" type="date" value="${esc(item.serviceDate||'')}"></div><div class="desc"><label>${item.kind==='disbursement'?'Disbursement':'Service description'}</label><textarea data-key="description" required>${esc(item.description)}</textarea></div><div><label>Fee basis</label><select data-key="rateUnit">${['hr','day','flat'].map(u=>`<option value="${u}" ${u===item.rateUnit?'selected':''}>${{hr:'Hourly',day:'Daily',flat:'Fixed'}[u]}</option>`).join('')}</select></div><div><label>Quantity</label><input data-key="quantity" type="number" min="0.0001" step="0.0001" value="${item.quantity}" required></div><div><label>Rate (R)</label><input data-key="rate" type="number" min="0" step="0.01" value="${item.rate}" required></div>${button('×','removeLine',index)}</div>`).join('');updateTotals();}
function updateTotals(){try{const t=invoiceTotals(editorItems,data.settings);$('#invoice-totals').textContent=`Subtotal ${money(t.subtotal)} · VAT ${money(t.vat)} · Total ${money(t.total)}`;}catch{$('#invoice-totals').textContent='Enter valid quantities and rates.';}}
function invoicePayload(){const f=$('#invoice-form'),v=Object.fromEntries(new FormData(f));const i=data.invoices.find(i=>i.id===f.dataset.id);return{...v,id:i?.id,expectedVersion:i?._version,lineItems:editorItems.map(x=>({...x}))};}
async function previewDraft(){syncMatter();const p=invoicePayload(),firm=data.firms.find(f=>f.id===p.clientId);if(!firm||!p.matterName.trim())return toast('Select a firm and enter a matter / project name first.');const t=invoiceTotals(p.lineItems,data.settings);const contact=firm.partners?.find(c=>c.id===p.partnerId);const snapshot={invoice:{...p,id:'DRAFT',clientName:firm.name,matterName:p.matterName,'Partner Name':contact?.name||firm.contact,amount:(t.total/100).toFixed(2),subtotalCents:t.subtotal,vatCents:t.vat,vatRegistered:data.settings.vatRegistered,vatNumber:data.settings.vatNumber,vatRate:data.settings.vatRate},firm,settings:data.settings};const blob=await(await import('./pdf.js')).makePDF(snapshot);if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=URL.createObjectURL(blob);let panel=$('#draft-preview');if(!panel){panel=document.createElement('div');panel.id='draft-preview';$('#invoice-form').append(panel);}panel.innerHTML='<h3>Draft invoice preview</h3><iframe title="Draft invoice PDF" class="pdf"></iframe>';panel.querySelector('iframe').src=pdfURL;panel.scrollIntoView({behavior:'smooth'});}
function viewInvoice(id){const i=data.invoices.find(i=>i.id===String(id));if(!i)return toast('Invoice could not be found. Refresh the records and try again.');const firm=data.firms.find(f=>f.id===i.clientId);modal('Invoice '+esc(i.id),`<div class="invoice-paper"><div class="invoice-top"><div><h2>${esc(data.settings.practiceName)}</h2><p>${esc(i.clientName)}<br>Attention: ${esc(i.partnerName||firm?.contact)}<br>${esc(firm?.address)}</p></div><div>${badge(i)}<p>Invoice date ${displayDate(i.date)}<br>Due ${displayDate(i.dueDate)}</p></div></div><p><strong>Matter:</strong> ${esc(i.matterName)}<br>Reference: ${esc(i.reference)}</p>${table(['Service date','Description','Basis','Quantity','Rate','Total'],(i.items||[]).map(x=>`<tr><td>${displayDate(x.serviceDate)}</td><td>${esc(x.description)}${x.kind==='disbursement'?'<small>Disbursement</small>':''}</td><td>${esc(x.rateUnit)}</td><td>${esc(x.quantity)}</td><td>${money(decimal(x.rate))}</td><td>${money(lineTotal(x))}</td></tr>`))}<div class="totals">Total ${money(i.amountCents)}<br>Outstanding ${i.paidCents===null&&i.status==='PAID'?'Historical PAID · receipts unverified':money(outstanding(i))}</div></div><h3>Payment history</h3>${table(['Date','Received','Allocated','Reference','State'],data.payments.filter(p=>p.invoiceId===id).map(p=>`<tr><td>${displayDate(p.date)}</td><td>${money(p.amountCents)}</td><td>${money(p.allocatedCents)}</td><td>${esc(p.reference)}</td><td>${p.reversed==='TRUE'?'Reversed':'Recorded'}</td></tr>`))}`,i.status==='DRAFT'?button('Edit draft','editDraft',id)+button('Preview PDF','pdf',id)+button('Download PDF','download',id):i.status==='ISSUING'?button('Complete PDF issue','completeIssue',id,'primary'):button('Preview PDF','pdf',id)+button('Download PDF','download',id)+button('Print','print',id)+button('Email / WhatsApp','share',id,'primary')+button('Record payment','payment',id)+button('Credit note','creditNote',id)+button('Cancel invoice','cancelInvoice',id));}
async function invoiceBlob(i){if(i.pdfFileId){const r=await fetch('/api/file?id='+encodeURIComponent(i.pdfFileId),{cache:'no-store'});if(!r.ok)throw Error('Private PDF could not be loaded.');return r.blob();}if(!i.issuedSnapshot)toast('Historical PDF reconstructed from current records. No original PDF is registered.');const snapshot=i.issuedSnapshot?JSON.parse(i.issuedSnapshot):{invoice:{...i,lineItems:i.items,vatRegistered:false,vatCents:0,subtotalCents:i.amountCents},firm:data.firms.find(f=>f.id===i.clientId)||{},settings:data.settings};return(await import('./pdf.js')).makePDF(snapshot);}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
const invoiceFilename=i=>`Invoice_${i.id}_DJ_Badenhorst.pdf`;
async function base64(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(blob);});}
async function completeIssue(id){const i=data.invoices.find(i=>i.id===id);if(!i||i.status!=='ISSUING')return;const blob=await invoiceBlob(i);await save('document',{recordId:id,expectedVersion:i._version,kind:'invoice',base64:await base64(blob),name:invoiceFilename(i),mimeType:'application/pdf'});close();viewInvoice(id);}
function paymentForm(id){const inv=data.invoices.find(i=>i.id===id);modal('Record payment',`<form id="payment-form"><div class="fields">${select('Invoice','invoiceId','<option value="">Select invoice</option>'+data.invoices.filter(i=>!['DRAFT','CANCELLED','ISSUING'].includes(i.status)).map(i=>`<option value="${esc(i.id)}" ${i.id===id?'selected':''}>${esc(i.id)} · ${esc(i.clientName)} · ${money(outstanding(i))}</option>`).join(''))}${field('Amount received (R)','amount',inv?outstanding(inv)/100:'','number','step="0.01" min="0.01" required')}${field('Payment date','date',today(),'date','required')}${field('Reference','reference','','text','required')}${select('Method','method',['EFT','Cash','Card','Other'].map(m=>'<option>'+m+'</option>').join(''))}</div><p class="small">The full receipt is counted once in income. Any amount above the invoice balance remains a firm credit.</p><div class="modal-foot"><button type="submit" class="primary">Record payment</button></div></form>`);}
function transactionForm(id,type='EXPENSE'){const t=data.transactions.find(t=>t.id===id)||{};modal(id?'Edit cash record':type==='EXPENSE'?'Record expense':'Record income',`<form id="transaction-form" data-id="${esc(id)}"><div class="fields">${field('Date','date',dateISO(t.date)||'','date','required')}${field('Amount (R)','amount',t.amount?Math.abs(Number(t.amount)):'','number','step="0.01" min="0.01" required')}${select('Type','type',transactionTypes.map(v=>`<option ${v===(t.type||type)?'selected':''}>${v}</option>`).join(''))}${field('Category','category',t.category,'text','required')}${textarea('Description','description',t.description)}${field('Reference','reference',t.reference)}</div>${t.date&&!dateISO(t.date)?`<p class="notice">Original malformed date: ${esc(t.date)}. Enter the correct date from your source record.</p>`:''}<div class="modal-foot"><button class="primary" type="submit">Save cash record</button></div></form>`);}
function shareForm(id,kind='invoice'){
const i=kind==='invoice'?data.invoices.find(i=>i.id===id):null,f=data.firms.find(f=>f.id===(i?i.clientId:id)),partner=f?.partners?.find(p=>p.id===i?.partnerId);
if(!f)return toast('Recipient firm could not be found.');
if(i&&['DRAFT','ISSUING','CANCELLED'].includes(i.status))return toast('Only issued, active invoices can be sent.');
const contact=i?.partnerName||f.contact||'Attorney',phone=i?.['Partner Phone']||partner?.phone||f.phone||'',email=i?.partnerEmail||partner?.email||f.email||'',subject=kind==='invoice'?'Invoice '+id+' | Advocate DJ Badenhorst':'Statement as at '+displayDate(today())+' | Advocate DJ Badenhorst';
modal(kind==='invoice'?'Send invoice '+esc(id):'Send statement · '+esc(f.name),`<form id="share-form" data-id="${esc(id)}" data-kind="${kind}"><p><strong>LexChamber Accounts</strong><br>From: ${ACCOUNTS_EMAIL}<br>On behalf of Advocate DJ Badenhorst</p><div class="fields">${field('Email recipient','emailRecipient',email,'email')}${field('WhatsApp recipient','recipient',phone)}${field('Email subject','subject',subject)}${textarea('Message for review','message',deliveryMessage({kind,contact,id,matter:i?.matterName,amount:i?money(i.amountCents):money(data.invoices.filter(x=>x.clientId===id).reduce((n,x)=>n+outstanding(x),0)),due:i?displayDate(i.dueDate):displayDate(today())}))}</div><p id="email-status" class="small">Checking direct email connection…</p><p class="small">Email drafts include the PDF and the accounts sender address. Open the downloaded .eml draft in Thunderbird and check the From account before sending. WhatsApp uses the account signed in on your device. When opening WhatsApp, attach the downloaded PDF before sending.</p><p class="small" id="delivery-result" role="status">Review the recipient and message before sending. Opening a draft or share screen does not confirm delivery.</p><div class="modal-foot"><button type="submit" name="email" id="direct-email" disabled class="primary">Send email with PDF</button><button type="submit" name="draft">Download email draft with PDF</button><button type="submit" name="native">Share PDF through device</button><button type="submit" name="fallback">Download and open WhatsApp</button></div></form>`);
fetch('/api/status',{cache:'no-store'}).then(r=>r.json()).then(v=>{if(!document.querySelector('#share-form'))return;$('#direct-email').disabled=!v.emailConfigured;$('#email-status').textContent=v.emailConfigured?'Direct email is connected. Sends from '+ACCOUNTS_EMAIL+'.':'Direct email awaits a Brevo API key and verified sender. Email drafts and WhatsApp sharing are available now.';}).catch(()=>{if($('#email-status'))$('#email-status').textContent='Direct email status is unavailable. Use an email draft or WhatsApp.';});
}
async function deliveryDocument(id,kind){if(kind==='invoice'){const i=data.invoices.find(i=>i.id===id);return {blob:await invoiceBlob(i),name:invoiceFilename(i)};}return {blob:await(await import('./pdf.js')).makeStatementPDF(data.firms.find(f=>f.id===id),statementRows(id),data.invoices.filter(i=>i.clientId===id).reduce((n,i)=>n+outstanding(i),0),{...data.settings,email:ACCOUNTS_EMAIL},today()),name:'Statement_'+id+'_'+today()+'.pdf'};}
function statementRows(firmId){let rows=[];for(const i of data.invoices.filter(i=>i.clientId===firmId&&i.status!=='DRAFT'))rows.push([displayDate(i.date),'Invoice '+i.id,i.matterName,money(i.amountCents),i.paidCents===null&&i.status==='PAID'?'PAID · unverified':money(outstanding(i))]);for(const p of data.payments.filter(p=>p.clientId===firmId))rows.push([displayDate(p.date),p.reversed==='TRUE'?'Reversed receipt':p.method==='Historical balance'?'Historical paid balance':'Payment',p.reference,money(p.amountCents),`Allocated ${money(p.allocatedCents)} · credit ${money(p.creditCents)}`]);for(const c of data.credits.filter(c=>c.clientId===firmId))rows.push([displayDate(c.date),'Credit note '+c.id,c.reason,money(c.amountCents),'Invoice '+c.invoiceId]);return rows;}
function statement(id){const f=data.firms.find(f=>f.id===id);modal(esc(f.name)+' · statement',`<div class="invoice-paper"><div class="invoice-top"><div><h2>${esc(data.settings.practiceName)}</h2><p>${esc(data.settings.letterhead)}<br>${esc(data.settings.address)}<br>${esc(data.settings.email)} · ${esc(data.settings.phone)}</p></div><div><h2>Statement</h2><p>${displayDate(today())}</p></div></div><p><strong>${esc(f.name)}</strong><br>${esc(f.address)}<br>Attention: ${esc(f.contact)}</p>${table(['Date','Entry','Matter / reference','Amount','Balance / allocation'],statementRows(id))}<div class="totals">Outstanding ${money(data.invoices.filter(i=>i.clientId===id).reduce((n,i)=>n+outstanding(i),0))}</div><p>${esc(data.settings.terms)}</p><h3>Banking particulars</h3><p>${esc(data.settings.accountName)} · ${esc(data.settings.bank)}<br>Account: ${esc(data.settings.accountNumber)} · Branch: ${esc(data.settings.branchCode)}</p></div>`,button('Email / WhatsApp','shareStatement',id,'primary')+button('Export statement PDF','statementPDF',id)+button('Export CSV','statementCSV',id));}
function csv(heads,rows,name){const quote=v=>'"'+String(v??'').replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"';downloadBlob(new Blob(['\uFEFF'+[heads,...rows].map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),name);}
function financialRows(){const s=financialSummary(data,from,to),rows=[['Period',displayDate(from)+' to '+displayDate(to)],['Basis','Cash receipts and recorded practice expenses'],['Recorded practice income',money(s.receipts)],['Recorded practice expenses',money(s.expenses)],['Cash surplus before tax adjustments',money(s.surplus)],['Fees invoiced (separate from receipts)',money(s.invoiced)],['Review transactions in period',String(s.review)],['Undated / invalid-date ledger entries',String(s.undated)]];for(const c of s.categories)rows.push([c.type+' · '+c.category,money(c.cents)]);for(const a of s.balances)rows.push(['Unreconciled balance · '+a.name,money(a.balance)]);if(s.currentDebtors!==null)rows.push(['Current outstanding debtor balances',money(s.currentDebtors)]);for(const x of data.settings.financialPosition?.entries||[])rows.push([x.kind+' · '+x.label+' (as at '+displayDate(data.settings.financialPosition.date)+')',money(decimal(x.amount))]);return rows;}
function financialStatements(){const s=financialSummary(data,from,to),pairs=transferCandidates(data.transactions),position=data.settings.financialPosition;return heading('Financial statements','Practice accounts and supporting bank records.',button('Export CSV','financialCSV')+button('Export PDF','financialPDF','', 'primary'))+`${!data.accountingReady?'<div class="notice"><strong>Bank-account setup required</strong><p>The Financial Statements view works with existing records. Bank accounts and uploads require the updated Apps Script and backed-up schema setup.</p><a href="/Code_Working_Copy.txt" download>Download updated Apps Script</a></div>':''}<div class="toolbar">${field('From','from',from,'date')}${field('To','to',to,'date')}${button('Apply dates','applyDates')}${button('Current financial year','financialYear')}</div><div class="notice"><strong>Draft financial statements · review before use</strong><p>Internal transfers and personal spending are excluded from practice income and expenses. REVIEW items and invalid dates are excluded. Bank imports are not automatically allocated to invoices. Tax adjustments, opening balances and reconciliation must be reviewed before these figures are used for tax returns.</p></div><div class="cards">${[['Practice receipts',s.receipts],['Practice expenses',s.expenses],['Cash surplus before adjustments',s.surplus]].map(x=>`<div class="card"><div class="label">${x[0]}</div><div class="value">${connected?money(x[1]):'—'}</div><small>${displayDate(from)} – ${displayDate(to)}</small></div>`).join('')}</div><div class="panel"><div class="panel-head"><h2>Income and expenditure · cash basis</h2></div>${table(['Type','Category','Amount'],s.categories.map(c=>`<tr><td>${esc(c.type)}</td><td>${esc(c.category)}</td><td class="number">${money(c.cents)}</td></tr>`))}<div class="totals">Cash surplus ${money(s.surplus)}</div><p>${s.review} entries in this period need classification. ${s.undated} ledger entries have invalid or missing dates. Historical cumulative payment balances are not added again as income.</p></div><div class="panel"><div class="panel-head"><h2>Bank accounts</h2>${button('Add bank account','bankAccount','','primary')}</div><p>Set an opening balance immediately before the opening date. For a credit card, enter an amount owed as a negative balance. Account registers are backed by separate tabs; reports count only the central Transactions ledger.</p>${table(['Account','Type','Opening date','Opening balance','Calculated balance at '+displayDate(to),''],s.balances.map(a=>`<tr><td>${esc(a.name)}<small>•••• ${esc(a.lastFour)} · ${esc(a.sheetName)}</small></td><td>${esc(a.kind)}</td><td>${displayDate(a.openingDate)}</td><td>${money(decimal(a.openingBalance||0))}</td><td>${money(a.balance)}<small>Unreconciled · includes personal and transfer cash movements</small></td><td>${button('Edit','bankAccount',a.id)} ${button('Upload statement','bankUpload',a.id)}</td></tr>`))}</div><div class="panel"><h2>Statement register</h2>${table(['Account','Statement','Uploaded','State',''],data.bankStatements.map(st=>`<tr><td>${esc(data.bankAccounts.find(a=>a.id===st.accountId)?.name)}</td><td>${esc(st.name)}</td><td>${displayDate(st.uploadedAt)}</td><td>${esc(st.status)}<small>${st.importedCount||0} imported rows</small></td><td><a href="/api/file?id=${encodeURIComponent(st.fileId)}" target="_blank" rel="noopener">Open private source</a></td></tr>`))}<p class="small">PDF uploads are source documents awaiting extraction. Upload a bank CSV export or transcribed CSV to import reviewed entries. No PDF upload alone changes the ledger.</p></div><div class="panel"><div class="panel-head"><h2>Statement of financial position · working schedule</h2>${button('Add / edit balances','position')}</div><p>Bank balances are calculated from opening balances and imported movements. Debtors are available as current balances only. Add reviewed assets, liabilities and capital below; these figures are provisional until the accounts are reconciled.</p>${table(['Item','Type','Value'],[...s.balances.map(a=>`<tr><td>${esc(a.name)}</td><td>${a.balance<0?'Liability':'Asset'}</td><td>${money(Math.abs(a.balance))}</td></tr>`),...(s.currentDebtors===null?[]:[`<tr><td>Current debtors</td><td>Asset</td><td>${money(s.currentDebtors)}</td></tr>`]),...(position?.entries||[]).map(x=>`<tr><td>${esc(x.label)}<small>As at ${displayDate(position.date)}</small></td><td>${esc(x.kind)}</td><td>${money(decimal(x.amount))}</td></tr>`)])}<p class="small">${s.currentDebtors===null?'Historical debtor balances require payment-by-payment reconciliation; current balances are not presented as historical balances.':''} This is a working schedule, not a balanced final balance sheet.</p></div><div class="panel"><h2>Potential inter-account transfer matches</h2>${table(['From / to','Date','Amount'],pairs.map(p=>`<tr><td>${esc(data.bankAccounts.find(a=>a.id===p.a.accountId)?.name)} ↔ ${esc(data.bankAccounts.find(a=>a.id===p.b.accountId)?.name)}</td><td>${displayDate(p.a.date)} / ${displayDate(p.b.date)}</td><td>${money(p.cents)}</td></tr>`))}<p class="small">Equal opposite amounts within three days are suggestions only. Transfer classifications are excluded from practice income and expense totals even before matching.</p></div>`;}
function bankAccountForm(id){if(!data.accountingReady)return toast('Update Apps Script and run initialisePractice before adding bank accounts.');const a=data.bankAccounts.find(a=>a.id===id)||{};modal(id?'Edit bank account':'Add bank account',`<form id="bank-account-form" data-id="${esc(id)}"><div class="fields">${field('Account name','name',a.name,'text','required')}${select('Account type','kind',['CHEQUE','CREDIT_CARD','SAVINGS','OTHER'].map(k=>`<option ${k===a.kind?'selected':''}>${k}</option>`).join(''))}${field('Last four digits only','lastFour',a.lastFour,'text','maxlength="4" pattern="[0-9]{0,4}"')}${field('Opening date','openingDate',a.openingDate||financialYear(),'date','required')}${field('Opening balance (R) · negative if owed','openingBalance',a.openingBalance||'0','number','step="0.01" required')}</div><p>The balance is immediately before the opening date. Use zero only if it is the true opening balance. No historical transactions are automatically assigned to this account.</p><label class="check"><input name="archived" type="checkbox" ${a.archived==='TRUE'?'checked':''}>Archive account</label><div class="modal-foot"><button type="submit" class="primary">Save bank account</button></div></form>`);}
