function bankMapForm(){const c=bankUploadState.csv;const opts='<option value="">Not used</option>'+c.headers.map((h,i)=>`<option value="${i}">${esc(h)}</option>`).join('');modal('Map bank statement columns',`<form id="bank-map-form"><p>${c.rows.length} source rows. Review each transaction before saving. Dates must be DD/MM/YYYY or YYYY-MM-DD.</p><div class="fields">${['date','description','amount','debit','credit','reference'].map(k=>select(k==='amount'?'Signed amount (positive received, negative paid)':k[0].toUpperCase()+k.slice(1),k,opts)).join('')}${select('Decimal separator','separator','<option value=".">Point · 1,234.56</option><option value=",">Comma · 1.234,56</option>')}</div><p>Choose either a signed Amount column or both Debit and Credit columns. Credit-card exports must use positive for repayments and negative for spending.</p><div class="modal-foot"><button type="submit" class="primary">Review transactions</button></div></form>`);for(const k of ['date','description','amount','debit','credit','reference']){const index=c.headers.findIndex(h=>({date:/^(date|transaction date|posting date)$/i,description:/^(description|details|narrative)$/i,amount:/^(amount|transaction amount)$/i,debit:/^(debit|debits|withdrawal)$/i,credit:/^(credit|credits|deposit)$/i,reference:/^(reference|ref)$/i}[k]).test(h));if(index>=0)$('#'+k).value=String(index);}}
function bankReviewForm(){modal('Review bank transactions',`<form id="bank-review-form"><p>${bankUploadState.rows.length} entries. Types are suggestions; edit them before import. Entries matching prior imports for this account will be skipped. Legacy entries without an assigned account cannot be matched automatically; reconcile them before importing the same period. Identical same-day entries without a bank reference need special care when statements overlap.</p><div class="table-wrap"><table><thead><tr><th>Import</th><th>Date / description</th><th>Amount</th><th>Type</th><th>Category</th></tr></thead><tbody>${bankUploadState.rows.map((r,i)=>`<tr data-bank-index="${i}"><td><input type="checkbox" class="bank-include" checked aria-label="Import row ${i+1}" style="width:20px"></td><td>${displayDate(r.date)}<small>${esc(r.description)}</small></td><td>${money(decimal(r.amount))}</td><td><select class="bank-type" aria-label="Transaction type">${transactionTypes.map(t=>`<option ${t===r.type?'selected':''}>${t}</option>`).join('')}</select></td><td><input class="bank-category" value="${esc(r.category)}" aria-label="Category"></td></tr>`).join('')}</tbody></table></div><p class="small">Import adds bank receipts once to Transactions. Historical payment summaries remain separate; invoice allocations require reconciliation.</p><div class="modal-foot"><button type="submit" class="primary">Confirm reviewed import</button></div></form>`);}
function positionForm(){const p=data.settings.financialPosition||{date:to,entries:[]};modal('Reviewed financial-position balances',`<form id="position-form">${field('As at date','positionDate',p.date,'date','required')}<div id="position-entries">${p.entries.map(positionEntry).join('')}</div>${button('Add item','positionAdd')}<p>Enter reviewed assets, liabilities and capital. Do not repeat bank balances or debtors shown above. These are supporting balances, not automatic tax adjustments.</p><div class="modal-foot"><button type="submit" class="primary">Save balances</button></div></form>`);}
function positionEntry(x={}){return `<div class="position-entry fields" style="margin:18px 0;border-top:1px solid var(--border);padding-top:18px"><div>${select('Type','positionKind',['Asset','Liability','Capital'].map(k=>`<option ${x.kind===k?'selected':''}>${k}</option>`).join(''))}</div><div><label>Description</label><input class="position-label" value="${esc(x.label)}" required></div><div><label>Amount (R)</label><input class="position-amount" type="number" min="0" step="0.01" value="${esc(x.amount)}" required></div>${button('Remove','positionRemove')}</div>`;}

function reportRows(){const r=report(data,from,to),labels={invoiced:'Fees invoiced',receipts:'Recorded receipts',expenses:'Recorded expenses',surplus:'Cash surplus',outstanding:'Outstanding fees',overdue:'Overdue fees'};const rows=Object.entries(r).map(([k,v])=>[labels[k],money(v)]);for(const f of data.firms)rows.push(['Firm balance: '+f.name,money(data.invoices.filter(i=>i.clientId===f.id).reduce((s,i)=>s+outstanding(i),0))]);for(const m of data.matters)rows.push(['Matter fees: '+m.title,money(report({...data,invoices:data.invoices.filter(i=>i.matterId===m.id)},from,to).invoiced)]);ageing(data.invoices,to).forEach((n,i)=>rows.push(['Ageing: '+['Current','1–30 days','31–60 days','61–90 days','Over 90 days'][i],money(n)]));return rows;}
async function exportReport(title,heads,rows,filename){const blob=await(await import('./pdf.js')).makeReportPDF(title,heads,rows,data.settings);downloadBlob(blob,filename);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const{action,id}=el.dataset;try{if(action==='navigate'){view=id;filter='';document.body.classList.remove('menu-open');$('#mobile-menu').setAttribute('aria-expanded','false');render();}else if(action==='settings'){view='Settings';render();}else if(action==='refresh')await refresh();else if(action==='close')close();else if(action==='retry'){await retry();close();}else if(action==='discard'){if(confirm('Discard this pending submission? A previous request may already have reached the spreadsheet. Refresh and review it first.')){pending=null;await refresh();}}else if(action==='review')modal('Records requiring review',`<ul>${data.issues.map(i=>'<li>'+esc(i)+'</li>').join('')}</ul><p>Review original evidence before correcting any value. No dates or historical payment amounts are inferred.</p>`);else if(action==='newFirm'||action==='firm')firmForm(id);else if(action==='addContact')$('#contacts').insertAdjacentHTML('beforeend',contactFields());else if(action==='removeContact')el.closest('.contact').remove();else if(action==='newMatter'||action==='matter')matterForm(id);else if(action==='newInvoice'||action==='editDraft'||action==='editInvoice')invoiceForm(id);else if(action==='addLine'||action==='addDisbursement'){editorItems.push({id:crypto.randomUUID(),serviceDate:today(),description:'',quantity:1,rate:action==='addDisbursement'?0:data.settings.hourlyRate,rateUnit:action==='addDisbursement'?'flat':'hr',kind:action==='addDisbursement'?'disbursement':'fee'});renderLines();}else if(action==='removeLine'){editorItems.splice(Number(id),1);renderLines();}else if(action==='previewDraft')await previewDraft();else if(action==='invoice')viewInvoice(id);else if(action==='newPayment'||action==='payment')paymentForm(id);else if(action==='completeIssue')await completeIssue(id);else if(action==='expense'||action==='income'||action==='transaction')transactionForm(id,action==='income'?'INCOME':'EXPENSE');else if(['pdf','download','print'].includes(action)){const i=data.invoices.find(i=>i.id===id),blob=await invoiceBlob(i);if(action==='download')downloadBlob(blob,invoiceFilename(i));else{modal('PDF · invoice '+esc(id),'<iframe title="Invoice PDF" class="pdf"></iframe>');pdfURL=URL.createObjectURL(blob);$('iframe.pdf').src=pdfURL;if(action==='print')$('iframe.pdf').onload=()=>{try{$('iframe.pdf').contentWindow.print();}catch{toast('Use the PDF viewer’s print control.');}}}}else if(action==='share')shareForm(id);else if(action==='reverse'){const p=data.payments.find(p=>p.id===id),reason=prompt('Reason for reversal:');if(reason)await save('reversePayment',{id,reason,expectedVersion:p._version});}else if(action==='cancelInvoice'||action==='creditNote'){const i=data.invoices.find(i=>i.id===id);modal(action==='creditNote'?'Issue credit note':'Cancel invoice',`<form id="correction-form" data-id="${esc(id)}" data-kind="${action==='creditNote'?'creditNote':'cancel'}"><div class="fields">${textarea('Reason','reason')}${action==='creditNote'?field('Credit amount (R)','amount','','number','step="0.01" min="0.01" required')+field('Credit date','date',today(),'date','required'):''}</div><p>The original issued PDF is retained. This change is recorded in the audit log.</p><div class="modal-foot"><button type="submit" class="primary">Confirm ${action==='creditNote'?'credit note':'cancellation'}</button></div></form>`);}else if(action==='shareStatement')shareForm(id,'statement');else if(action==='statement')statement(id);else if(action==='statementCSV')csv(['Date','Entry','Matter/reference','Amount','Balance/allocation'],statementRows(id),'Attorney_Statement.csv');else if(action==='statementPDF')downloadBlob(await(await import('./pdf.js')).makeStatementPDF(data.firms.find(f=>f.id===id),statementRows(id),data.invoices.filter(i=>i.clientId===id).reduce((n,i)=>n+outstanding(i),0),data.settings,today()),'Attorney_Statement_DJ_Badenhorst.pdf');else if(action==='financialCSV')csv(['Item','Value'],financialRows(),'Practice_Financial_Statements_'+from+'.csv');else if(action==='financialPDF')await exportReport('Draft practice financial statements '+displayDate(from)+' to '+displayDate(to),['Item','Value'],financialRows(),'Practice_Financial_Statements_'+from+'.pdf');else if(action==='financialYear'){from=financialYear();to=today();render();}else if(action==='bankAccount')bankAccountForm(id);else if(action==='bankUpload')bankUploadForm(id);else if(action==='position')positionForm();else if(action==='positionAdd')$('#position-entries').insertAdjacentHTML('beforeend',positionEntry());else if(action==='positionRemove')el.closest('.position-entry').remove();else if(action==='reportCSV')csv(['Metric','Amount'],reportRows(),'Practice_Report_'+from+'.csv');else if(action==='reportPDF')await exportReport('Practice report '+displayDate(from)+' to '+displayDate(to),['Metric','Amount'],reportRows(),'Practice_Report.pdf');else if(action==='applyDates'){from=$('#from').value;to=$('#to').value;render();}else if(action==='sheet5')modal('Sheet5 · preserved bank records',table(['Date','Description','Amount','Balance'],data.sheet5.map(r=>`<tr><td>${esc(r.Date)}</td><td>${esc(r.Description)}</td><td>${esc(r.Amount)}</td><td>${esc(r.Balance)}</td></tr>`)));else if(action==='audit')modal('Financial audit log',table(['When','Actor','Action','Record','Operation'],data.audit.slice().reverse().map(a=>`<tr><td>${esc(a.date)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${esc(a.recordId)}</td><td>${esc(a.operationId)}</td></tr>`)));else if(action==='migration')modal('Missing ID migration',`<p>${raw.migrationPreview?.length||0} records have no ID. A backup is created before repair; only ID cells are filled. Original dates and amounts remain unchanged.</p>${table(['Tab','Row'],(raw.migrationPreview||[]).map(r=>`<tr><td>${esc(r.tab)}</td><td>${r.row}</td></tr>`))}`,button('Back up and repair missing IDs','runMigration','','primary'));else if(action==='runMigration'){await save('migrateIds',{expectedVersion:raw.migrationVersion});close();}else if(action==='receipt')modal('Attach private expense receipt',`<form id="receipt-form" data-id="${esc(id)}"><label>PDF, JPEG or PNG · maximum 5 MB</label><input name="attachment" type="file" accept="application/pdf,image/png,image/jpeg" required><div class="modal-foot"><button type="submit" class="primary">Save receipt</button></div></form>`);}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filter=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}const row=e.target.closest('.line-item');if(row&&e.target.dataset.key){editorItems[Number(row.dataset.index)][e.target.dataset.key]=e.target.value;updateTotals();}});
document.addEventListener('change',e=>{if(e.target.id==='clientId')fillFirmSelectors();if(e.target.id==='matterName')syncMatter();if(e.target.id==='status-filter'){statusFilter=e.target.value;render();}const row=e.target.closest('.line-item');if(row&&e.target.dataset.key==='rateUnit'){const item=editorItems[Number(row.dataset.index)];item.rateUnit=e.target.value;item.rate=item.rateUnit==='day'?data.settings.dailyRate:item.rateUnit==='flat'?data.settings.fixedRate:data.settings.hourlyRate;renderLines();}if(e.target.id==='date-filter'||e.target.id==='from'||e.target.id==='to'){if(view==='Invoices'){const enabled=$('#date-filter')?.checked,lo=$('#from')?.value,hi=$('#to')?.value;document.querySelectorAll('tbody tr').forEach(row=>{const id=row.querySelector('strong')?.textContent,i=data.invoices.find(i=>i.id===id),date=dateISO(i?.date);row.hidden=!!(enabled&&i&&(!date||date<lo||date>hi));});}}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f)),id=f.dataset.id;try{if(!connected&&f.id!=='share-form')throw Error('Connect to the practice sheet before saving.');if(f.id==='bank-account-form'){const old=data.bankAccounts.find(a=>a.id===id);await save('bankAccount',{...v,id:id||undefined,expectedVersion:old?._version,archived:f.elements.archived.checked});close();}else if(f.id==='bank-upload-form'){const file=f.elements.statement.files[0];if(file.size>5000000)throw Error('File exceeds 5 MB.');bankUploadState={accountId:v.accountId,file};if(file.name.toLowerCase().endsWith('.csv')){bankUploadState.csv=parseCSV(await file.text());if(bankUploadState.csv.rows.length>500)throw Error('Import up to 500 rows at a time; split larger CSV statements.');bankMapForm();}else if(file.name.toLowerCase().endsWith('.pdf')){await save('bankStatement',{accountId:v.accountId,name:file.name,mimeType:'application/pdf',base64:await base64(file)});close();toast('PDF stored privately. Entries await extraction; no ledger transactions were added.');}else throw Error('Choose a PDF or CSV bank statement.');}else if(f.id==='bank-map-form'){if(v.date===''||v.description===''||(v.amount===''&&(v.debit===''||v.credit==='')))throw Error('Map Date, Description and either Amount or Debit and Credit.');bankUploadState.rows=mappedRows(bankUploadState.csv,v);bankReviewForm();}else if(f.id==='bank-review-form'){const rows=[...f.querySelectorAll('[data-bank-index]')].filter(row=>row.querySelector('.bank-include').checked).map(row=>({...bankUploadState.rows[Number(row.dataset.bankIndex)],type:row.querySelector('.bank-type').value,category:row.querySelector('.bank-category').value.trim()}));if(!rows.length||rows.some(r=>!r.category))throw Error('Select entries and complete their categories.');f.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);const beforeCount=data.transactions.length;const st=await save('bankStatement',{accountId:bankUploadState.accountId,name:bankUploadState.file.name,mimeType:'text/csv',base64:await base64(bankUploadState.file)});for(let index=0;index<rows.length;index+=20){await save('bankImport',{accountId:bankUploadState.accountId,statementId:st.recordId,rows:rows.slice(index,index+20),final:index+20>=rows.length});f.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);}const added=data.transactions.length-beforeCount;close();toast(added+' rows imported; '+(rows.length-added)+' duplicates skipped. Refresh confirms the spreadsheet records.');}else if(f.id==='position-form'){const entries=[...f.querySelectorAll('.position-entry')].map(row=>({kind:row.querySelector('select').value,label:row.querySelector('.position-label').value.trim(),amount:row.querySelector('.position-amount').value}));await save('settings',{values:{financialPosition:{date:v.positionDate,entries}},expectedVersion:raw.settingsVersion});close();}else if(f.id==='firm-form'){const old=data.firms.find(x=>x.id===id);const partners=[...f.querySelectorAll('.contact')].map(c=>({...old?.partners?.find(x=>x.id===c.dataset.id),id:c.dataset.id,name:c.querySelector('[name="contactName"]').value,email:c.querySelector('[name="contactEmail"]').value,phone:c.querySelector('[name="contactPhone"]').value}));await save('firm',{...v,id:id||undefined,expectedVersion:old?._version,partners,archived:f.elements.archived.checked});close();}else if(f.id==='matter-form'){const old=data.matters.find(x=>x.id===id);await save('matter',{...v,id:id||undefined,expectedVersion:old?._version,archived:f.elements.archived.checked});close();}else if(f.id==='invoice-form'){const kind=e.submitter?.name==='amend'?'amend':e.submitter?.name==='issue'?'issue':'draft';if(kind==='amend'&&!v.amendmentReason?.trim())throw Error('Give a reason for this amendment.');syncMatter();let payload=invoicePayload();if(!payload.matterId){const firm=data.firms.find(x=>x.id===payload.clientId);if(!firm||!payload.matterName.trim())throw Error('Select a firm and enter a matter / project name.');const created=await save('matter',{title:payload.matterName.trim(),clientId:firm.id,status:'OPEN',dateOpened:payload.date,description:'',notes:'',archived:false});$('#matterId').value=created.recordId;payload=invoicePayload();}const r=await save(kind,payload);if(kind==='issue'||kind==='amend')await completeIssue(r.recordId);else close();}else if(f.id==='payment-form'){const i=data.invoices.find(i=>i.id===v.invoiceId);if(!i)throw Error('Select an invoice.');await save('payment',{...v,expectedVersion:i._version});close();}else if(f.id==='transaction-form'){await save('transaction',{...v,id:id||undefined,expectedVersion:data.transactions.find(t=>t.id===id)?._version});close();}else if(f.id==='settings-form'){const values={...v,vatRegistered:f.elements.vatRegistered.checked,detailsReviewed:f.elements.detailsReviewed.checked,paymentDays:Number(v.paymentDays)};await save('settings',{values,expectedVersion:raw.settingsVersion});}else if(f.id==='correction-form'){await save(f.dataset.kind,{...v,invoiceId:id,expectedVersion:data.invoices.find(i=>i.id===id)._version});close();}else if(f.id==='receipt-form'){const file=f.elements.attachment.files[0];if(file.size>5000000)throw Error('File exceeds 5 MB.');await save('document',{recordId:id,expectedVersion:data.transactions.find(t=>t.id===id)._version,kind:'receipt',base64:await base64(file),name:file.name,mimeType:file.type});close();}else if(f.id==='share-form'){
const kind=f.dataset.kind||'invoice',mode=e.submitter?.name;
if(['email','draft'].includes(mode)&&(!v.emailRecipient||!f.elements.emailRecipient.checkValidity()))throw Error('Enter a valid email recipient.');
if(!v.message.trim()||!v.subject.trim())throw Error('Enter a subject and message.');
const number=mode==='fallback'?whatsappNumber(v.recipient):null;
const {blob,name}=await deliveryDocument(id,kind),file=new File([blob],name,{type:'application/pdf'});
if(mode==='email'){
const btn=e.submitter;btn.disabled=true;$('#delivery-result').textContent='Submitting email…';
try{const r=await fetch('/api/send-email',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({to:v.emailRecipient,subject:v.subject,message:v.message,filename:name,base64:await base64(blob)})});const result=await r.json();if(!result.ok)throw Error(result.message||'Email was not confirmed.');$('#delivery-result').textContent='Accepted by the email provider for delivery to '+v.emailRecipient+'. Inbox delivery is not confirmed.';btn.textContent='Submitted to email provider';}catch(err){$('#delivery-result').textContent=err.message+' Check your Brevo sent log before sending again.';btn.disabled=false;}
}else if(mode==='draft'){downloadBlob(emailDraft({to:v.emailRecipient,subject:v.subject,message:v.message,filename:name,base64:await base64(blob)}),name.replace(/\.pdf$/i,'.eml'));$('#delivery-result').textContent='Email draft downloaded with its PDF attachment. Open it in Thunderbird, review the From account, then send.';
}else if(mode==='native'&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:v.subject,text:v.message});toast('Share screen closed. Delivery has not been confirmed.');
}else{const phone=number||whatsappNumber(v.recipient);downloadBlob(blob,name);const a=document.createElement('a');a.href='https://wa.me/'+phone+'?text='+encodeURIComponent(v.message);a.target='_blank';a.rel='noopener';a.click();$('#delivery-result').textContent='PDF downloaded. Attach it in WhatsApp before sending.';}
}}catch(err){if(err.name!=='AbortError')toast(err.message);}});
$('#refresh').addEventListener('click',refresh);render();refresh();
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'open_invoice_draft',title:'Open invoice draft',description:'Open the invoice editor. Does not save or issue an invoice.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(Object.keys(input||{}).length)throw Error('No arguments expected.');invoiceForm();return{editorOpen:true,saved:false};}});document.modelContext.registerTool({name:'refresh_practice_records',title:'Refresh practice records',description:'Read the authoritative spreadsheet and update the visible app.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(input){if(Object.keys(input||{}).length)throw Error('No arguments expected.');return{connected:await refresh(),invoiceCount:data.invoices.length,lastRefresh:lastRefresh?.toISOString()};}});}

$('#mobile-menu').addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');$('#mobile-menu').setAttribute('aria-expanded',String(open));});
